// i960 profiling: where the recompiled i960 program's time goes, as
// tgp_profile.h does for the TGP. Built only with M2_I960_PROFILE
// (scripts/recompile.py --i960-profile, CMake -DM2_I960_PROFILE=ON;
// scripts/build_vita.py --i960-profile, written to perf.log), which also needs
// i960 code generated by m2recomp --profile. Without it the runtime and the
// generated code are unchanged.
//
// What it measures:
//   - time: every gen::run call (GameLoop) is timed with the frontend's clock.
//     It holds the i960 and what runs inside its bus accesses and lockstep
//     events: the TGP (removed when M2_TGP_PROFILE times it too) and the
//     board's scheduled callbacks (vblank, timers, sound commands: timed in
//     Lockstep::apply and removed);
//   - work: m2recomp --profile counts the executions of each basic block (one
//     increment at its end; without --fast_inaccuracy the same blocks, for
//     the counters only) and writes what each block holds (I960BlockInfo);
//     executions x contents = bus loads and stores in words, integer ALU,
//     multiplies, divides (a library call on the Vita's Cortex-A9, which has
//     no divide instruction), compares, branches, calls and returns (register
//     frame spills), indirect transfers (through the chunk's switch), FP;
//   - the bus calls that reach M2Board, by region (work RAM, other RAM, ROM,
//     texture RAM, the TGP's ports, other devices): the difference with the
//     blocks' loads and stores is what the Vita's direct work-RAM pass made
//     direct;
//   - dispatches (switch entries), chunk entries, lockstep slow paths;
//   - the hottest blocks of the window.
// Counters never change what the i960 computes.
#pragma once

#include <cstddef>
#include <cstdint>

namespace rt {

// What a basic block of the i960 program holds, counted per instruction by
// m2recomp --profile (always defined: the recompiler uses it too).
enum I960Op : uint8_t {
    I960OpLoad,     // words loaded through the bus (ld 1, ldl 2, ldt 3, ldq 4; byte and short loads 1)
    I960OpStore,    // words stored through the bus
    I960OpAlu,      // integer, logic, shift, mov, lda
    I960OpMul,      // mulo, muli, emul
    I960OpDiv,      // divo, divi, remo, remi, modi, ediv
    I960OpCompare,  // cmp*, test*, concmp*, chkbit, scanbyte, bbc/bbs
    I960OpCond,     // conditional branch (b*, cmpob*, cmpib*, bbc/bbs)
    I960OpBranch,   // b, bal
    I960OpCall,     // call, callx (the runtime's do_call: a register frame)
    I960OpRet,      // ret (do_ret)
    I960OpIndirect, // bx, balx, callx, ret: back through the chunk's switch
    I960OpFp,       // FP arithmetic, compare, move, conversion (host double)
    I960OpFpMath,   // sin, cos, tan, atan, log, exp, sqrt, rem, scale (libm)
    I960OpSys,      // synmov, synmovq, modpc, modac, flushreg
    kI960Ops
};

struct I960BlockInfo {
    uint32_t start;         // first instruction's address
    uint16_t length;        // instructions
    uint8_t ops[kI960Ops];  // per execution of the block
};

} // namespace rt

#ifdef M2_I960_PROFILE

#include <vector>

namespace rt {

// Where a bus call landed (M2Board::read_* / write_*).
enum I960BusRegion : uint8_t { BusWorkRam, BusRam, BusRom, BusTex, BusTgp, BusDev, BusUnmapped, kBusRegions };

struct I960Profile {
    uint64_t (*clock)() = nullptr; // host ticks (set by the frontend); null: no timing
    uint64_t ticks_per_second = 1000000;
    uint64_t runs = 0, ticks = 0;  // gen::run calls and their time
    uint64_t board_calls = 0, board_ticks = 0; // Lockstep callbacks run inside gen::run, and their time
    uint64_t bus_r[kBusRegions]{}, bus_w[kBusRegions]{};
};
inline I960Profile i960_profile; // inline: the bus and the lockstep count without pulling in the report

namespace i960gen { // m2recomp --profile
extern const I960BlockInfo blocks[];
extern const uint32_t block_count;
extern uint64_t block_hits[];
extern uint64_t dispatches;    // chunk switch entries: chunk entries + indirect transfers + re-dispatches
extern uint64_t chunk_entries; // gen::run's calls of a chunk function
extern uint64_t events;        // --fast_inaccuracy block_events (a lockstep event due at a block start)
} // namespace i960gen

// The report of one window: start() at its beginning, format() at its end.
class I960ProfileReport {
public:
    void start(uint64_t i960_instructions, uint64_t interrupts);
    // frames: emulated frames in the window; cpu_mhz: for cycles (0: none);
    // tgp_ms: the TGP's own time per frame, removed from gen::run's (negative:
    // unknown); whole_ms: a frontend time per frame that contains gen::run's,
    // named by whole (null: none).
    size_t format(char *out, size_t size, uint64_t frames, uint64_t i960_instructions, uint64_t interrupts, int cpu_mhz,
                  double tgp_ms, double whole_ms, const char *whole) const;

private:
    I960Profile at_{};
    uint64_t instructions_ = 0, interrupts_ = 0, dispatches_ = 0, chunk_entries_ = 0, events_ = 0;
    std::vector<uint64_t> hits_;
    mutable std::vector<uint32_t> order_;
};

} // namespace rt

#endif // M2_I960_PROFILE
